<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
$base=rtrim($argv[1]??'http://127.0.0.1:8000','/');$c=require'C:\quality_system_config\database.php';$pdo=new PDO("mysql:host={$c['host']};port={$c['port']};dbname={$c['name']};charset=utf8mb4",$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$ephemeralValue='E2E-'.bin2hex(random_bytes(12));$emails=['Admin'=>'e2e-admin-'.bin2hex(random_bytes(5)).'@invalid.test','Reviewer'=>'e2e-reviewer-'.bin2hex(random_bytes(5)).'@invalid.test'];$ids=[];
function request(string $url,?array $post=null,?string $cookie=null):array{$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>20]);if(getenv('QUALITY_E2E_INSECURE_TLS')==='1'){curl_setopt($ch,CURLOPT_SSL_VERIFYPEER,false);curl_setopt($ch,CURLOPT_SSL_VERIFYHOST,0);}if($cookie){curl_setopt($ch,CURLOPT_COOKIEJAR,$cookie);curl_setopt($ch,CURLOPT_COOKIEFILE,$cookie);}if($post!==null){curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,$post);}$raw=curl_exec($ch);if($raw===false)throw new RuntimeException(curl_error($ch));$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$headerSize=curl_getinfo($ch,CURLINFO_HEADER_SIZE);return[$status,substr($raw,$headerSize),substr($raw,0,$headerSize)];}
function expect(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);echo"PASS $message\n";}
function login(string $base,string $email,string $ephemeralValue):string{$cookie=tempnam(sys_get_temp_dir(),'qse2e-');[$status,$body]=request("$base/login.php",null,$cookie);expect($status===200,'login form loads');preg_match('/name="_csrf_token" value="([a-f0-9]+)"/',$body,$m);expect(isset($m[1]),'login form contains CSRF token');[$status]=request("$base/login.php",['_csrf_token'=>$m[1],'email'=>$email,'password'=>$ephemeralValue],$cookie);expect($status===302,'valid login redirects');return$cookie;}
try{
    $insert=$pdo->prepare('INSERT INTO users(full_name,email,password_hash,role,status) VALUES(?,?,?,?,?)');foreach($emails as $role=>$email){$insert->execute(["E2E $role",$email,password_hash($ephemeralValue,PASSWORD_DEFAULT),$role,'Active']);$ids[]=(int)$pdo->lastInsertId();}
    [$status,$body,$headers]=request("$base/login.php");expect($status===200,'public login endpoint responds');expect(str_contains($headers,'Content-Security-Policy:'),'security headers are present');
    $admin=login($base,$emails['Admin'],$ephemeralValue);foreach([['/users.php','admin can access user administration'],['/tasks','admin can access scoped task list'],['/tasks/create','admin can access task creation'],['/program-specifications','admin can access program specifications'],['/program-specifications/create','admin can access program specification creation'],['/program-manuals','admin can access program manuals'],['/program-manuals/create','admin can create program manuals'],['/program-manuals/1','admin can view a program manual'],['/program-manuals/1/download','admin can securely download a program manual'],['/course-reports','admin can access course reports'],['/course-reports/create','admin can access course report creation'],['/committee_tasks_dashboard.php','admin can access committee task dashboard']] as [$path,$message]){[$status]=request($base.$path,null,$admin);expect($status===200,$message);}[$status]=request("$base/export_course_reports_csv.php",null,$admin);expect(in_array($status,[200,404],true),'report export is authorization-safe');[$status]=request("$base/download_file.php?id=2147483647",null,$admin);expect($status===404,'authorized download hides missing records');[$status]=request("$base/delete_user.php?id=2147483647",null,$admin);expect($status===405,'destructive GET is rejected');[$status]=request("$base/delete_user.php",['id'=>2147483647],$admin);expect($status===403,'destructive POST without CSRF is rejected');
    $reviewer=login($base,$emails['Reviewer'],$ephemeralValue);[$status,$body]=request("$base/users.php",null,$reviewer);expect($status===403&&str_contains($body,'Access denied'),'reviewer cannot access administration');foreach([['/tasks','reviewer can access scoped task list'],['/program-specifications','reviewer can access scoped program specifications'],['/program-manuals','reviewer can access scoped program manuals'],['/course-reports','reviewer can access scoped course reports']] as [$path,$message]){[$status]=request($base.$path,null,$reviewer);expect($status===200,$message);}foreach([['/tasks/create','reviewer cannot access task creation'],['/program-specifications/create','reviewer cannot create program specifications'],['/program-manuals/create','reviewer cannot create program manuals'],['/course-reports/create','reviewer cannot create course reports'],['/upload_file.php?id=2147483647','reviewer cannot access upload action']] as [$path,$message]){[$status,$body]=request($base.$path,null,$reviewer);expect($status===403&&str_contains($body,'Access denied'),$message);}[$status]=request("$base/download_file.php?id=2147483647",null,$reviewer);expect($status===404,'reviewer reaches authorized download controller');
    echo"HTTP end-to-end suite passed.\n";
}finally{if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$pdo->prepare("DELETE FROM users WHERE id IN ($marks)")->execute($ids);}foreach(glob(sys_get_temp_dir().DIRECTORY_SEPARATOR.'qse2e-*')?:[]as$file)@unlink($file);}
